// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint8 calls) public {
        vm.assume(calls > 0);
        for (uint i = 0; i < calls; i++) {
            vm.deal(address(this), 1 ether);
            (bool ok,) = address(c).call{value: 1}("");
            require(ok, "receive call failed");
        }
        assertTrue(c.depositsCount() == calls);
    }
}
